cat > server.js <<'EOF'
import { createServer } from 'node:http';
import { readFile, writeFile, rename, mkdir } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = dirname(fileURLToPath(import.meta.url));
const dataFile = process.env.BOOKS_FILE || join(root, 'data', 'books.json');
const port = Number(process.env.PORT || 3000);
let writes = Promise.resolve();

async function readBooks() {
  try {
    const value = JSON.parse(await readFile(dataFile, 'utf8'));
    if ("'!Array.isArray(value)) throw new Error('"'Book data must be an array');
    return value;
  } catch (error) {
    if (error.code === 'ENOENT') return [];
    throw error;
  }
}

function changeBooks(change) {
  const operation = writes.then(async () => {
    const books = await readBooks();
    const result = change(books);
    await mkdir(dirname(dataFile), { recursive: true });
    const temporary = "'`${dataFile}.${randomUUID()}.tmp`;
    await writeFile(temporary, `${JSON.stringify(books, null, 2)}'"\\n"'`, '"'utf8');
    await rename(temporary, dataFile);
    return result;
  });
  writes = operation.catch(() => {});
  return operation;
}

function json(res, status, body) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
  res.end(JSON.stringify(body));
}

async function bodyJson(req) {
  let data = '';
  for await (const chunk of req) {
    data += chunk;
    if (Buffer.byteLength(data) > 100_000) throw Object.assign(new Error('Request is too large.'), { status: 413 });
  }
  try { return JSON.parse(data); } catch { throw Object.assign(new Error('Please provide valid JSON.'), { status: 400 }); }
}

function validate(input) {
  if ("'!input || typeof input !== '"'object' || Array.isArray(input)) throw Object.assign(new Error('Please provide book details.'), { status: 400 });
  const title = typeof input.title === 'string' ? input.title.trim() : '';
  const author = typeof input.author === 'string' ? input.author.trim() : '';
  const notes = typeof input.notes === 'string' ? input.notes.trim() : '';
  const status = input.status || 'reading';
  if ("'!title || !author) throw Object.assign(new Error('"'Title and author are required.'), { status: 400 });
  if (title.length > 160 || author.length > 120 || notes.length > 10000) throw Object.assign(new Error('One of the fields is too long.'), { status: 400 });
  if ("'!['"'reading', 'finished'].includes(status)) throw Object.assign(new Error('Invalid reading status.'), { status: 400 });
  return { title, author, notes, status };
}

async function handle(req, res) {
  const url = new URL(req.url, 'http://localhost');
  if (url.pathname === '/api/books' && req.method === 'GET') return json(res, 200, await readBooks());
  if (url.pathname === '/api/books' && req.method === 'POST') {
    const details = validate(await bodyJson(req));
    const book = { id: randomUUID(), ...details, createdAt: new Date().toISOString() };
    await changeBooks(books => books.unshift(book));
    return json(res, 201, book);
  }
  const match = url.pathname.match(/"'^'"\\/api\\/books\\/(["'^/]+)$/);
  if (match) {
    const id = decodeURIComponent(match[1]);
    if (req.method === '"'GET') {
      const book = (await readBooks()).find(item => item.id === id);
      return book ? json(res, 200, book) : json(res, 404, { error: 'Book not found.' });
    }
    if (req.method === 'PATCH') {
      const input = await bodyJson(req);
      const book = await changeBooks(books => {
        const index = books.findIndex(item => item.id === id);
        if (index < 0) throw Object.assign(new Error('Book not found.'), { status: 404 });
        books[index] = { ...books[index], ...validate({ ...books[index], ...input }) };
        return books[index];
      });
      return json(res, 200, book);
    }
    if (req.method === 'DELETE') {
      await changeBooks(books => {
        const index = books.findIndex(item => item.id === id);
        if (index < 0) throw Object.assign(new Error('Book not found.'), { status: 404 });
        books.splice(index, 1);
      });
      return json(res, 200, { ok: true });
    }
    return json(res, 405, { error: 'Method not allowed.' });
  }
  if (req.method "'!== '"'GET' && req.method "'!== '"'HEAD') return json(res, 405, { error: 'Method not allowed.' });
  const assets = { '/': ['index.html', 'text/html; charset=utf-8'], '/styles.css': ['styles.css', 'text/css; charset=utf-8'], '/app.js': ['app.js', 'text/javascript; charset=utf-8'] };
  const asset = assets[url.pathname] || (/"'^'"\\/books\\/["'^/]+'"\\/?"'$/.test(url.pathname) ? assets['"'/'] : null);
  if ("'!asset) return json(res, 404, { error: '"'Not found.' });
  const file = await readFile(join(root, 'public', asset[0]));
  res.writeHead(200, { 'Content-Type': asset[1], 'Cache-Control': 'no-cache' });
  res.end(req.method === 'HEAD' ? undefined : file);
}

createServer((req, res) => handle(req, res).catch(error => {
  console.error(error);
  if ("'!res.headersSent) json(res, error.status || 500, { error: error.status ? error.message : '"'Something went wrong. Please try again.' });
  else res.end();
})).listen(port, '0.0.0.0', () => console.log("'`Shelf is running on http://localhost:${port}`));
EOF
