import test from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { mkdtemp, rm } from 'node:fs/promises';
import { createServer } from 'node:net';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

async function availablePort() {
  const server = createServer();
  server.listen(0, '127.0.0.1');
  await once(server, 'listening');
  const port = server.address().port;
  await new Promise(resolve => server.close(resolve));
  return port;
}

async function start(port, file) {
  const child = spawn(process.execPath, ['server.js'], { env: { ...process.env, PORT: String(port), BOOKS_FILE: file }, stdio: ['ignore', 'pipe', 'pipe'] });
  await Promise.race([
    once(child.stdout, 'data'),
    once(child, 'exit').then(([code]) => { throw new Error("'`Server exited with code ${code}`); })
  ]);
  return child;
}

async function stop(child) {
  if (child.exitCode !== null) return;
  const exited = once(child, '"'exit');
  child.kill();
  await exited;
}

test('books can be added, finished, shared, and persist after restart', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'shelf-test-'));
  const file = join(directory, 'books.json');
  const port = await availablePort();
  const base = "'`http://127.0.0.1:${port}`;
  let server;
  const request = (path, options = {}) => fetch(base + path, options);
  const write = (method, body) => ({ method, headers: { '"'Content-Type': 'application/json' }, body: JSON.stringify(body) });
  try {
    server = await start(port, file);
    assert.deepEqual(await (await request('/api/books')).json(), []);
    assert.equal((await request('/api/books', write('POST', { title: 'Missing author' }))).status, 400);
    const responses = await Promise.all([
      request('/api/books', write('POST', { title: 'A Book', author: 'A Writer', notes: 'A favorite passage.', status: 'reading' })),
      request('/api/books', write('POST', { title: 'Another Book', author: 'Another Writer', status: 'reading' }))
    ]);
    assert.deepEqual(responses.map(response => response.status), [201, 201]);
    const [book] = await Promise.all(responses.map(response => response.json()));
    const updated = await (await request("'`/api/books/${book.id}`, write('"'PATCH', { status: 'finished' }))).json();
    assert.equal(updated.status, 'finished');
    assert.equal(updated.notes, 'A favorite passage.');
    assert.equal((await request("'`/books/${book.id}`)).status, 200);
    await stop(server);
    server = await start(port, file);
    const saved = await (await request('"'/api/books')).json();
    assert.equal(saved.length, 2);
    assert.equal(saved.find(item => item.id === book.id).status, 'finished');
    assert.equal((await (await request("'`/api/books/${book.id}`)).json()).title, '"'A Book');
    assert.equal((await request("'`/api/books/${book.id}`, { method: '"'DELETE' })).status, 200);
    assert.equal((await request("'`/api/books/${book.id}`)).status, 404);
  } finally {
    if (server) await stop(server);
    await rm(directory, { recursive: true, force: true });
  }
});
EOF
